SELECT jsonb_build_object('customer',(SELECT count(*) FROM app.customer_profiles WHERE id='bb08464f-0d2f-5462-bfa8-9917f461f4b4'),'command',(SELECT count(*) FROM platform.runtime_command_receipt WHERE id IN ('40ade94f-1adb-5803-9722-51ee4f1b7e9e','6f7be8c5-2df6-5bfa-9141-f6c614a2dadd')), 'history',(SELECT count(*) FROM app.customer_profile_lifecycle_event WHERE customer_profile_id='bb08464f-0d2f-5462-bfa8-9917f461f4b4'),'evidence',(SELECT count(*) FROM platform.owner_mutation_evidence WHERE aggregate_kind='CustomerProfile' AND aggregate_id='bb08464f-0d2f-5462-bfa8-9917f461f4b4'),'outbox',(SELECT count(*) FROM platform.runtime_outbox_message WHERE command_receipt_id IN ('40ade94f-1adb-5803-9722-51ee4f1b7e9e','6f7be8c5-2df6-5bfa-9141-f6c614a2dadd')),'track_enrollments',(SELECT count(*) FROM app.track_enrollment_receipt WHERE profile_id='bb08464f-0d2f-5462-bfa8-9917f461f4b4'),'coherent',EXISTS(SELECT 1 FROM app.customer_profiles c
