  AND e.evidence_body='{"schema":"database-owner-evidence.v1","owner":"customer_buyer_profile","model":"CustomerProfile","primaryKey":{"id":"bb08464f-0d2f-5462-bfa8-9917f461f4b4"},"prior":null,"committed":{"id":"bb08464f-0d2f-5462-bfa8-9917f461f4b4","userId":"1a2aa6e9-f7bc-558a-9c2f-b34f02a9d562","status":"active","revision":"0","privacyGeneration":"0"},"decisionRef":"customer-controls-v1"}'::jsonb AND e.evidence_digest=encode(sha256(convert_to(e.evidence_body::text,'UTF8')),'hex')
 WHERE c.id='bb08464f-0d2f-5462-bfa8-9917f461f4b4' AND c.user_id='1a2aa6e9-f7bc-558a-9c2f-b34f02a9d562' AND c.status='active' AND c.revision=0 AND c.privacy_generation=0
